  private void startLogin(){pool.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(BASE+"/auth/telegram?next=/account").openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(10000);String loc=c.getHeaderField("Location");c.disconnect();if(loc==null)throw new IOException("Не удалось начать вход.");Uri uri=Uri.parse(loc);String token=uri.getQueryParameter("resume");if(token==null||!token.matches("[A-Za-z0-9_-]{20,64}"))throw new IOException("Не удалось получить код входа.");HttpURLConnection ready=(HttpURLConnection)new URL(BASE+loc).openConnection();ready.setConnectTimeout(10000);ready.setReadTimeout(10000);int status=ready.getResponseCode();ready.disconnect();if(status!=200)throw new IOException("Не удалось подключить вход Telegram. Попробуй позже.");loginToken=token;loginTries=0;main.post(()->{Intent intent=new Intent(Intent.ACTION_VIEW,Uri.parse("https://t.me/AuraFXAuthBot?start=login_"+token));try{startActivity(intent);}catch(Exception ex){message("Установи Telegram, чтобы подтвердить вход.");}message("Подтверди вход в Telegram и вернись в AuraFX.");});pollLogin();}catch(Exception e){main.post(()->message(e.getMessage()));}});}
