  private void adminLeadDetail(JSONObject lead){adminShell("Заявка #"+lead.optInt("id"));add(page,text(lead.optString("product"),24,WHITE,true),19);String[] keys={"marketplace","count","style","deadline","contact","comment","client_comment","source","created_at"};String[] labels={"Площадка","Карточек","Стиль","Срок","Контакт","Комментарий","Правки клиента","Источник","Создано"};LinearLayout detail=card();for(int i=0;i<keys.length;i++){String value=lead.optString(keys[i],"");if(!value.isEmpty()&&!value.equals("null"))add(detail,text(labels[i]+": "+value,14,i==4?WHITE:MUTED,i==4),i==0?0:8);}add(page,detail,15);add(page,text("ЭТАП ЗАКАЗА",12,CYAN,true),22);String[] codes={"new","contacted","review","revision","done","spam"};for(String code:codes){add(page,button((code.equals(lead.optString("status"))?"✓  ":"○  ")+statusName(code),false,()->new android.app.AlertDialog.Builder(this).setTitle("Изменить статус?").setMessage("Заявка #"+lead.optInt("id")+" → "+statusName(code)+". Клиент может получить уведомление.").setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(dialog,which)->{try{JSONObject body=new JSONObject();body.put("status",code);request("PATCH","/api/admin/leads/"+lead.optInt("id"),body,(d,e)->{if(e!=null)message(e.getMessage());else{message("Статус сохранён");adminLeads();}});}catch(Exception e){message(e.getMessage());}}).show()),8);}}
  private void adminReviews(){adminShell("Модерация · публикация в общей ленте AuraFX");LinearLayout list=column();add(page,list,17);int generation=adminGeneration;request("GET","/api/admin/reviews",null,(d,e)->{if(current!=11||generation!=adminGeneration)return;if(e!=null){message(e.getMessage());return;}JSONArray a=d.optJSONArray("reviews");if(a==null||a.length()==0){add(list,text("Отзывов пока нет.",15,MUTED,false),0);return;}for(int i=0;i<a.length();i++){JSONObject review=a.optJSONObject(i);if(review==null)continue;int id=review.optInt("id");LinearLayout c=card();add(c,text("#"+id+" · "+review.optString("status")+" · "+"★".repeat(Math.max(1,Math.min(5,review.optInt("rating",5)))),13,CYAN,true),0);add(c,text(review.optString("name","Клиент"),18,WHITE,true),7);add(c,text(review.optString("text"),15,MUTED,false),8);if(!"approved".equals(review.optString("status")))add(c,button("Опубликовать",true,()->adminReviewStatus(id,"approved")),10);if(!"hidden".equals(review.optString("status")))add(c,button("Скрыть",false,()->adminReviewStatus(id,"hidden")),7);add(list,c,12);}});}
  private void adminReviewStatus(int id,String status){try{JSONObject body=new JSONObject();body.put("status",status);request("PATCH","/api/admin/reviews/"+id,body,(d,e)->{if(e!=null)message(e.getMessage());else adminReviews();});}catch(Exception e){message(e.getMessage());}}
  private void adminSupport(){adminShell("Диалоги с клиентами · ответы придут в их кабинет");LinearLayout list=column();add(page,list,15);int generation=adminGeneration;request("GET","/api/admin/support",null,(d,e)->{if(current!=11||generation!=adminGeneration)return;if(e!=null){message(e.getMessage());return;}JSONArray a=d.optJSONArray("threads");if(a==null||a.length()==0){add(list,text("Обращений пока нет.",15,MUTED,false),0);return;}for(int i=0;i<a.length();i++){JSONObject t=a.optJSONObject(i);if(t==null)continue;int id=t.optInt("id");add(list,button("#"+id+" · "+t.optString("subject")+("open".equals(t.optString("status"))?"  ·  Нужен ответ":"")+(t.optInt("unread")>0?"  ●":""),false,()->adminThread(id)),10);}});}
  private void adminThread(int id){adminShell("Обращение #"+id);LinearLayout list=column();add(page,list,14);EditText answer=field("Ответ клиенту",true);add(page,answer,18);add(page,button("Отправить ответ",true,()->{if(value(answer).isEmpty())return;try{JSONObject body=new JSONObject();body.put("body",value(answer));request("POST","/api/admin/support/"+id+"/messages",body,(d,e)->{if(e!=null)message(e.getMessage());else adminThread(id);});}catch(Exception e){message(e.getMessage());}}),8);add(page,button("Отметить решённым",false,()->{try{JSONObject body=new JSONObject();body.put("status","resolved");request("PATCH","/api/admin/support/"+id,body,(d,e)->{if(e!=null)message(e.getMessage());else adminSupport();});}catch(Exception e){message(e.getMessage());}}),8);int generation=adminGeneration;request("GET","/api/admin/support/"+id,null,(d,e)->{if(current!=11||generation!=adminGeneration)return;if(e!=null){message(e.getMessage());return;}JSONArray a=d.optJSONArray("messages");if(a==null)return;for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);if(m==null)continue;LinearLayout c=card();add(c,text("bot".equals(m.optString("sender_role"))?"✦ Помощник":"admin".equals(m.optString("sender_role"))?"Вы / AuraFX":"Клиент",12,CYAN,true),0);add(c,text(m.optString("body"),15,WHITE,false),6);add(list,c,9);}});}
  private void request(String method,String path,JSONObject body,Done done){pool.execute(()->{JSONObject result=null;Exception error=null;HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(BASE+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setRequestProperty("Accept","application/json");if(!session.isEmpty())c.setRequestProperty("Cookie",session);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();String cookie=c.getHeaderField("Set-Cookie");if(cookie!=null&&cookie.startsWith("afx_user=")){session=cookie.split(";",2)[0];getPreferences(0).edit().putString("session",session).apply();}InputStream stream=code>=400?c.getErrorStream():c.getInputStream();String raw=stream==null?"{}":new String(stream.readAllBytes(),StandardCharsets.UTF_8);if(stream!=null)stream.close();result=new JSONObject(raw);if(code>=400)throw new IOException(result.optString("error","Сервер ответил: "+code));}catch(Exception ex){error=ex;}finally{if(c!=null)c.disconnect();}JSONObject d=result;Exception e=error;main.post(()->{if(active)done.accept(d==null?new JSONObject():d,e);});});}
